package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClerkLimitException;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.statement.StatementRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Merges the person into another of the sheet; only a steward may, and not into themselves, nor when either of them is
 * retired. Their claims move to the other, keeping their numbers and dates, listed after the other's claims in the
 * order they were added, each losing any figure a statement bound it to. Their name and aliases become aliases of the
 * other. Their patrons are added to the other's (not the other themselves, no repeats); anyone naming them as patron
 * names the other instead (not themselves, no repeats). Their pool memberships move to the other (shares added when the
 * other is already a member). Their statements, holds, dated grades, watchers and contact are dropped, and they leave
 * the sheet.
 */
public class ApplyMerge {
    public void apply(@Val MergeInput input, @Val Person person, PersonRepository people, ClaimRepository claims,
            PersonAliasRepository aliases, PatronRepository patrons, PoolMemberRepository members,
            StatementRepository statements, WatchRepository watches, PersonGradeRepository grades,
            RoleRepository roles, EntityManager entityManager,
            @RequestHeader(name = "X-User", required = false) String userHeader, Out<PersonMerged> merged)
            throws InvalidPersonException, ClerkLimitException {
        String sheetId = person.getSheetId();
        String user = AuditUser.decode(userHeader);
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ClerkLimitException("Only a steward can merge people.");
        }
        claims.lockSheet(sheetId);
        entityManager.refresh(person);
        Person into = people.findByIdAndSheetId(input.intoId(), sheetId)
                .orElseThrow(() -> new InvalidPersonException("No such person on the sheet."));
        if (into.getId().equals(person.getId())) {
            throw new InvalidPersonException("A person cannot be merged into themselves.");
        }
        if (person.getRetiredFrom() != null || into.getRetiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be merged.");
        }
        Long from = person.getId();
        Long to = into.getId();

        // Claims: moved in the order they were added, each listed as the other's newest.
        List<Claim> moved = new ArrayList<>(claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> from.equals(c.getPersonId())).toList());
        moved.sort(Comparator.comparing(Claim::getId));
        for (Claim claim : moved) {
            claim.setPersonId(to);
            claim.bind(false, null);
            claims.saveAndFlush(claim);
            claims.relist(claim.getId());
        }

        // Name and aliases become the other's aliases.
        List<PersonAlias> theirAliases = aliases.findByPersonIdOrderByIdAsc(from);
        aliases.deleteAll(theirAliases);
        aliases.flush();
        aliases.save(new PersonAlias(sheetId, to, person.getName()));
        theirAliases.forEach(a -> aliases.save(new PersonAlias(sheetId, to, a.getAlias())));

        // Patrons: theirs added to the other's; those naming them name the other instead.
        for (Patron patron : patrons.findByPersonIdOrderByIdAsc(from)) {
            patrons.delete(patron);
            patrons.flush();
            if (!patron.getPatronId().equals(to) && !patrons.existsByPersonIdAndPatronId(to, patron.getPatronId())) {
                patrons.saveAndFlush(new Patron(sheetId, to, patron.getPatronId()));
            }
        }
        for (Patron naming : patrons.findByPatronIdOrderByIdAsc(from)) {
            patrons.delete(naming);
            patrons.flush();
            if (!naming.getPersonId().equals(to) && !patrons.existsByPersonIdAndPatronId(naming.getPersonId(), to)) {
                patrons.saveAndFlush(new Patron(sheetId, naming.getPersonId(), to));
            }
        }

        // Pool memberships move, adding shares where the other is already a member.
        for (PoolMember member : members.findByPersonIdOrderByIdAsc(from)) {
            var already = members.findByPoolIdAndPersonId(member.getPoolId(), to);
            if (already.isPresent()) {
                already.get().setShare(already.get().getShare().add(member.getShare()));
                members.delete(member);
                members.flush();
                members.saveAndFlush(already.get());
            } else {
                member.setPersonId(to);
                members.saveAndFlush(member);
            }
        }

        // Dropped: statements, watchers, dated grades; holds and contact go with the person.
        statements.deleteAll(statements.findByPersonIdOrderByIdAsc(from));
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from));
        grades.deleteAll(grades.findByPersonIdOrderByFromDateAsc(from));
        statements.flush();
        people.delete(person);
        people.flush();
        entityManager.refresh(into);
        merged.set(new PersonMerged(person.getName(), into));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimComment;
import net.officefloor.hq.app.claim.ClaimCommentRepository;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClerkLimitException;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.statement.StatementRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * Transfers the person to another sheet by id; only a steward may, not a retired person, not to this sheet itself,
 * nor to an archived sheet, nor when their contact is already on the other sheet. When their name or an alias of theirs
 * is already someone's name or alias there (ignoring case), they are merged into that person instead, exactly as a
 * merge does (not into a retired person): their claims are listed after that person's, each losing any figure a
 * statement bound it to, their name and aliases become that person's aliases, and their grades, terms and contact are
 * dropped. Otherwise they arrive there with every grade they were given
 * (and its from-date), their terms, contact and aliases, and their claims with their status, dates, notes, tags,
 * frozen dues, status logs and comments, listed in the same order. Each claim that had a number takes the other
 * sheet's next one, in the order they were opened (by the sheet's today when each was opened, then by the order they
 * were added). Figures a statement bound are lost (they have no statements there) and references are not carried.
 * They leave this sheet entirely: their claims, statements, holds, patron links (both ways), pool memberships and
 * watchers are dropped.
 */
public class ApplyTransfer {
    public void apply(@Val TransferInput input, @Val Person person, PersonRepository people, ClaimRepository claims,
            ClaimLogRepository logs, ClaimCommentRepository comments, PersonAliasRepository aliases,
            PatronRepository patrons, PoolMemberRepository members, StatementRepository statements,
            WatchRepository watches, PersonGradeRepository grades, RoleRepository roles, SheetRepository sheets,
            RateRepository rates, PeriodRepository periods, EntityManager entityManager,
            @RequestHeader(name = "X-User", required = false) String userHeader, Out<PersonTransferred> transferred)
            throws InvalidPersonException, ClerkLimitException {
        String sheetId = person.getSheetId();
        String user = AuditUser.decode(userHeader);
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new ClerkLimitException("Only a steward can transfer people.");
        }
        String to = input.toSheet();
        if (to.equals(sheetId)) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet.");
        }
        claims.lockSheet(sheetId);
        entityManager.refresh(person);
        if (person.getRetiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be transferred.");
        }
        Sheet target = sheets.findById(to).orElse(null);
        if (target != null && target.isArchived()) {
            throw new InvalidPersonException("The other sheet is archived.");
        }
        Long from = person.getId();
        List<PersonAlias> theirAliases = aliases.findByPersonIdOrderByIdAsc(from);
        List<String> names = new ArrayList<>();
        names.add(person.getName());
        theirAliases.forEach(a -> names.add(a.getAlias()));
        List<Person> onTarget = people.findListed(to);
        Person into = null;
        for (String name : names) {
            into = PersonAliasRepository.findByNameOrAlias(onTarget, aliases, to, name).orElse(null);
            if (into != null) {
                break;
            }
        }
        if (into != null && into.getRetiredFrom() != null) {
            throw new InvalidPersonException("A retired person cannot be merged.");
        }
        if (into == null && person.getContact() != null && people.existsBySheetIdAndContact(to, person.getContact())) {
            throw new InvalidPersonException("The contact is already in use on the other sheet.");
        }

        Rollup toBefore = Rollup.of(to, sheets, people, claims, rates, grades);
        if (target == null) {
            target = sheets.saveAndFlush(new Sheet(to));
        }
        claims.lockSheet(to);
        LocalDate today = target.getToday();

        // The person, with their grades over time and their aliases; or, merging, their name and aliases become the
        // other's aliases.
        List<PersonGrade> theirGrades = grades.findByPersonIdOrderByFromDateAsc(from);
        Person arrived;
        if (into != null) {
            arrived = into;
            Long intoId = into.getId();
            aliases.save(new PersonAlias(to, intoId, person.getName()));
            theirAliases.forEach(a -> aliases.save(new PersonAlias(to, intoId, a.getAlias())));
        } else {
            arrived = new Person(to, person.getName(), person.getGrade());
            arrived.setAddedOn(today);
            arrived.setTerms(person.getTerms());
            arrived.setContact(person.getContact());
            arrived.setTags(person.getTags());
            arrived.setOriginSheet(sheetId);
            arrived = people.saveAndFlush(arrived);
            for (PersonGrade grade : theirGrades) {
                PersonGrade copy = new PersonGrade(to, arrived.getId(), grade.getGrade(), grade.getFromDate());
                copy.setMadeOn(today);
                grades.save(copy);
            }
            for (PersonAlias alias : theirAliases) {
                aliases.save(new PersonAlias(to, arrived.getId(), alias.getAlias()));
            }
        }

        // Claims: copied in the order they are listed, so they keep it (after the other's, merging), each with its log
        // and comments.
        Long arrivedId = arrived.getId();
        List<Claim> theirs = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, from));
        theirs.sort(Comparator.comparing(Claim::getListed).thenComparing(Claim::getId));
        Map<Claim, Claim> copies = new LinkedHashMap<>();
        Map<Long, LocalDate> openedOn = new HashMap<>();
        for (Claim claim : theirs) {
            Claim copy = claims.saveAndFlush(claim.transferTo(to, arrivedId));
            copies.put(claim, copy);
            List<ClaimLog> lines = logs.findByClaimIdOrderByIdAsc(claim.getId());
            lines.stream().filter(l -> ClaimStatus.OPEN.name().equals(l.getStatus())).map(ClaimLog::getOnDate)
                    .findFirst().ifPresent(d -> openedOn.put(claim.getId(), d));
            lines.forEach(l -> logs.save(l.copyFor(copy)));
            logs.deleteAll(lines);
            List<ClaimComment> notes = comments.findByClaimIdOrderByIdAsc(claim.getId());
            notes.forEach(c -> comments.save(c.copyFor(copy)));
            comments.deleteAll(notes);
        }

        // Numbers: the other sheet's next, in the order the claims were opened.
        List<Claim> numbered = new ArrayList<>(theirs.stream().filter(c -> c.getNumber() != null).toList());
        numbered.sort(Comparator.comparing((Claim c) -> openedOn.getOrDefault(c.getId(), LocalDate.MAX))
                .thenComparing(Claim::getId));
        Map<String, String> renumbered = new HashMap<>();
        boolean perPeriod = target.periodNumberingOn();
        List<Period> targetPeriods = periods.findBySheetIdOrderByFromDateAscIdAsc(to);
        for (Claim claim : numbered) {
            Claim copy = copies.get(claim);
            String number;
            if (perPeriod) {
                String prefix = targetPeriods.stream().filter(p -> p.contains(copy.getDueBy())).map(Period::getName)
                        .findFirst().orElse(null);
                String seq = prefix == null ? "X" : "P:" + prefix;
                number = (prefix == null ? "X" : prefix) + "-" + claims.takeNextInSequence(to, seq);
            } else {
                claims.takeNextNumber(to);
                number = String.valueOf(claims.lastNumber(to));
            }
            copy.setNumber(number);
            renumbered.put(claim.getNumber(), number);
        }
        copies.forEach((claim, copy) -> {
            if (claim.getCorrects() != null) {
                copy.setCorrects(renumbered.get(claim.getCorrects()));
            }
            if (claim.getSplitFrom() != null) {
                copy.setSplitFrom(renumbered.get(claim.getSplitFrom()));
            }
            claims.save(copy);
        });
        claims.flush();

        // They leave this sheet entirely.
        claims.deleteAll(theirs);
        claims.flush();
        patrons.deleteAll(patrons.findByPersonIdOrderByIdAsc(from));
        patrons.deleteAll(patrons.findByPatronIdOrderByIdAsc(from));
        members.deleteAll(members.findByPersonIdOrderByIdAsc(from));
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from));
        statements.deleteAll(statements.findByPersonIdOrderByIdAsc(from));
        grades.deleteAll(theirGrades);
        aliases.deleteAll(theirAliases);
        aliases.flush();
        people.delete(person);
        people.flush();
        if (into != null) {
            entityManager.refresh(into);
        }
        transferred.set(new PersonTransferred(person.getName(), sheetId, to, toBefore,
                into == null ? null : into.getName()));
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimLog;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonGrades;
import net.officefloor.hq.app.rate.RateLogRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SettingLogRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Takes a statement for the person: records their due-total now, on the sheet's today, and binds each of
 * their claims that counts to the figure it has now (never its late charge, which keeps following the sheet's today); their claims that do not count (a person's unbound OPEN ones dated within a
 * hold among them) are unbound (live again).
 * <p>
 * Taken as of a date (on or before the sheet's today, and not before the person was added), it works the same out
 * as at the end of that date: every change made while the sheet's today was on or before it counts (a claim's status
 * and settled due, the rates, settings, grades, holds, retirement and the claims bound), every later change does not,
 * and that date stands in for the sheet's today. The claims that counted then are bound to their figures then; every
 * other claim of theirs is unbound.
 */
public class TakeStatement {
    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates, PersonGradeRepository grades,
            StatementRepository statements, BindingLogRepository bindings, ClaimLogRepository logs,
            RateLogRepository rateLogs, SettingLogRepository settingLogs, EntityManager entityManager,
            @RequestParam(name = "asOf", required = false) String asOfParam, Out<Statement> statementOut)
            throws InvalidPersonException {
        LocalDate asOf = parseAsOf(asOfParam, sheet, person);
        // Lock the person so two statements (or a statement and an edit) are taken one after the other.
        entityManager.refresh(person, LockModeType.PESSIMISTIC_WRITE);
        List<Claim> mine = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheet.getId(), person.getId());
        BindingLog binding = new BindingLog(sheet.getId(), person.getId(), sheet.getToday());
        String dueTotal;
        int counted = 0;
        if (asOf == null) {
            ClaimFigures figures = new ClaimFigures(rates.findInChain(sheet.getId()),
                    grades.gradesOf(person), sheet);
            dueTotal = figures.dueTotal(mine, sheet.getToday(), person);
            for (Claim claim : mine) {
                if (ClaimFigures.countsLive(claim, person, sheet.getToday())) {
                    BigDecimal figure = figures.figure(claim);
                    claim.bind(true, figure);
                    binding.bind(claim.getId(), figure);
                    counted++;
                } else {
                    claim.bind(false, null);
                }
            }
        } else {
            Sheet then = settingLogs.sheetAsOf(sheet, asOf);
            Person personThen = person.asOf(asOf);
            PersonGrades gradesThen = grades.gradesOf(person).asOf(asOf);
            ClaimFigures figures = new ClaimFigures(rates.chainOf(sheet.getId()).stream()
                    .flatMap(id -> rateLogs.ratesAsOf(id, asOf).stream()).toList(), gradesThen, then);
            Map<Long, BigDecimal> boundThen = bindings.boundAsOf(person.getId(), asOf);
            Map<Long, List<ClaimLog>> logged = logs.findBySheetIdOrderByIdAsc(sheet.getId()).stream()
                    .collect(Collectors.groupingBy(ClaimLog::getClaimId));
            // Each claim as it stood at the end of the date, by its status log; one not yet added then is left out.
            List<Claim> claimsThen = new ArrayList<>();
            for (Claim claim : mine) {
                Claim claimThen = claimAsOf(claim, logged.getOrDefault(claim.getId(), List.of()), boundThen, asOf);
                if (claimThen != null) {
                    claimsThen.add(claimThen);
                }
            }
            dueTotal = figures.dueTotal(claimsThen, asOf, personThen);
            Map<Long, Claim> byId = mine.stream().collect(Collectors.toMap(Claim::getId, c -> c));
            mine.forEach(c -> c.bind(false, null));
            for (Claim claimThen : claimsThen) {
                if (ClaimFigures.countsLive(claimThen, personThen, asOf)) {
                    BigDecimal figure = figures.figure(claimThen);
                    byId.get(claimThen.getId()).bind(true, figure);
                    binding.bind(claimThen.getId(), figure);
                    counted++;
                }
            }
        }
        claims.saveAllAndFlush(mine);
        bindings.saveAndFlush(binding);
        statementOut.set(statements.save(
                new Statement(sheet.getId(), person.getId(), dueTotal, sheet.getToday(), asOf, counted)));
    }

    /** The date the statement is taken as of: null when none is given; refuses one that is not a calendar date, one
     *  after the sheet's today, and one before the person was added. */
    private static LocalDate parseAsOf(String asOfParam, Sheet sheet, Person person) throws InvalidPersonException {
        if (asOfParam == null || asOfParam.isBlank()) {
            return null;
        }
        LocalDate asOf;
        try {
            asOf = LocalDate.parse(asOfParam.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("The statement's date must be a calendar date.");
        }
        if (asOf.isAfter(sheet.getToday())) {
            throw new InvalidPersonException("The statement's date is after the sheet's today.");
        }
        if (person.getAddedOn() != null && asOf.isBefore(person.getAddedOn())) {
            throw new InvalidPersonException("The person was not on the sheet on the statement's date.");
        }
        return asOf;
    }

    /** The claim as it stood at the end of the date: the status its log had then and the due it was settled at (when
     *  SETTLED then), bound as the person's bindings then had it; null when it had not been added by then. A claim
     *  with no log at all is taken as it stands. */
    private static Claim claimAsOf(Claim claim, List<ClaimLog> log, Map<Long, BigDecimal> boundThen, LocalDate asOf) {
        boolean stated = boundThen.containsKey(claim.getId());
        BigDecimal statedDue = boundThen.get(claim.getId());
        if (log.isEmpty()) {
            return claim.asOf(claim.getStatus(), claim.getDue(), stated, statedDue);
        }
        ClaimLog last = log.stream().filter(l -> !l.getOnDate().isAfter(asOf)).reduce((a, b) -> b).orElse(null);
        if (last == null) {
            return null;
        }
        ClaimStatus status = ClaimStatus.valueOf(last.getStatus());
        return claim.asOf(status, status == ClaimStatus.SETTLED ? last.getDue() : null, stated, statedDue);
    }
}
